using GaoApp.Web.Services.Assistant;
using GaoApp.Web.Services.CustomerService;
using Microsoft.AspNetCore.DataProtection;
using Xunit;

namespace GaoApp.Tests.Security;
public sealed class CustomerIdentityStoreTests:IDisposable
{
    private readonly string directory=Path.Combine(Path.GetTempPath(),"GaoCskhIdentityTests",Guid.NewGuid().ToString("N"));
    private readonly AssistantIntegrationTests.FixedClock clock=new();
    private readonly AssistantIntegrationTests.Monitor<CustomerServiceOptions> options=new(new(){DatabasePath="identity.db"});
    private readonly Guid visitor=Guid.NewGuid();private static readonly CustomerStaff Agent=new(1,1,"TEST agent",true,true,true);
    private CustomerServiceStore Store()=>new(new AssistantIntegrationTests.EnvironmentStub(directory),options,clock);
    private IDataProtector Protector {get{Directory.CreateDirectory(directory);return DataProtectionProvider.Create(new DirectoryInfo(Path.Combine(directory,"keys"))).CreateProtector("TEST identity");}}
    private CustomerConversation Start(CustomerServiceStore s){s.Configure(1,true,s.Settings(1).Version);var c=s.Start(1,visitor,new(Guid.NewGuid(),"TEST self declared","not proof",true));return s.StaffCommand(Agent,c.Id,new(Guid.NewGuid(),"claim",c.Version));}
    private static CustomerIdentityIssue Input(CustomerConversation c)=>new(Guid.NewGuid(),c.Version,42,"in_person","TEST counter identity checked",true);
    private (CustomerServiceStore S,CustomerConversation C,CustomerIdentityIssue I,CustomerIdentityCode Code) Issued(){var s=Store();var c=Start(s);var input=Input(c);return(s,c,input,s.IssueIdentity(Agent,c.Id,input,Protector));}
    [Fact]public void Contact_or_customer_id_never_grants_access_without_explicit_verification(){var s=Store();var c=Start(s);Assert.Equal(403,Assert.Throws<AssistantException>(()=>s.RequireIdentity(1,visitor,c.Id)).Status);Assert.False(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),"42")));}
    [Fact]public void Acknowledgement_retry_preserves_same_code_but_code_is_not_in_transcript(){var(s,c,input,code)=Issued();Assert.Equal(24,code.Code!.Length);Assert.Equal(code,s.IssueIdentity(Agent,c.Id,input,Protector));Assert.DoesNotContain(code.Code,System.Text.Json.JsonSerializer.Serialize(s.Get(1,visitor,c.Id)));Assert.Throws<AssistantException>(()=>s.IssueIdentity(Agent,c.Id,input with{CustomerId=43},Protector));}
    [Fact]public void Only_verified_owner_with_customer_rights_can_issue(){var s=Store();var c=Start(s);Assert.Equal(403,Assert.Throws<AssistantException>(()=>s.IssueIdentity(Agent with{CanVerify=false},c.Id,Input(c),Protector)).Status);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.IssueIdentity(Agent with{UserId=2},c.Id,Input(c),Protector)).Status);Assert.Throws<AssistantException>(()=>s.IssueIdentity(Agent,c.Id,Input(c) with{Confirmed=false},Protector));}
    [Fact]public void Five_failed_attempts_commit_and_lock_the_real_code(){var(s,c,_,code)=Issued();for(var n=0;n<5;n++)Assert.False(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),"WRONG")));Assert.False(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),code.Code!)));}
    [Fact]public void Code_expires_in_ten_minutes(){var(s,c,_,code)=Issued();clock.Now=clock.Now.AddMinutes(10);Assert.False(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),code.Code!)));}
    [Fact]public void Grant_expires_in_thirty_minutes_and_replay_cannot_extend_it(){var(s,c,_,code)=Issued();var input=new CustomerIdentityRedeem(Guid.NewGuid(),code.Code!);Assert.True(s.RedeemIdentity(1,visitor,c.Id,input));var proof=s.RequireIdentity(1,visitor,c.Id);clock.Now=clock.Now.AddMinutes(20);Assert.True(s.RedeemIdentity(1,visitor,c.Id,input));Assert.Equal(proof,s.RequireIdentity(1,visitor,c.Id));Assert.False(s.RedeemIdentity(1,visitor,c.Id,input with{RequestId=Guid.NewGuid()}));clock.Now=clock.Now.AddMinutes(10);Assert.Throws<AssistantException>(()=>s.RequireIdentity(1,visitor,c.Id));Assert.False(s.RedeemIdentity(1,visitor,c.Id,input));}
    [Fact]public void Code_cannot_open_another_visitor_conversation_or_store(){var(s,c,_,code)=Issued();Assert.Throws<AssistantException>(()=>s.RedeemIdentity(1,Guid.NewGuid(),c.Id,new(Guid.NewGuid(),code.Code!)));Assert.Throws<AssistantException>(()=>s.RedeemIdentity(2,visitor,c.Id,new(Guid.NewGuid(),code.Code!)));var next=s.Start(1,visitor,new(Guid.NewGuid(),"TEST same visitor",null,true));Assert.False(s.RedeemIdentity(1,visitor,next.Id,new(Guid.NewGuid(),code.Code!)));}
    [Fact]public async Task Concurrent_use_of_a_code_can_create_only_one_grant(){var(s,c,_,code)=Issued();var other=Store();var results=await Task.WhenAll(Task.Run(()=>s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),code.Code!))),Task.Run(()=>other.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),code.Code!))));Assert.Single(results,x=>x);Assert.Equal(42,s.RequireIdentity(1,visitor,c.Id).CustomerId);}
    [Theory][InlineData("revoke")][InlineData("close")][InlineData("end")][InlineData("disable")]
    public void Revocation_lifecycle_blocks_future_reads(string action){var(s,c,_,code)=Issued();Assert.True(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),code.Code!)));if(action=="revoke")s.RevokeIdentity(1,visitor,c.Id,Guid.NewGuid());if(action=="close"){c=s.StaffGet(Agent,c.Id);s.StaffCommand(Agent,c.Id,new(Guid.NewGuid(),"close",c.Version));}if(action=="end")s.Revoke(new(visitor,1,clock.Now.AddDays(7)));if(action=="disable")s.Configure(1,false,s.Settings(1).Version);Assert.Throws<AssistantException>(()=>s.RequireIdentity(1,visitor,c.Id));}
    [Fact]public void Reissue_invalidates_previous_code_and_active_grant(){var(s,c,_,first)=Issued();s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),first.Code!));c=s.StaffGet(Agent,c.Id);var next=s.IssueIdentity(Agent,c.Id,Input(c) with{CustomerId=43},Protector);Assert.Throws<AssistantException>(()=>s.RequireIdentity(1,visitor,c.Id));Assert.False(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),first.Code!)));Assert.True(s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),next.Code!)));Assert.Equal(43,s.RequireIdentity(1,visitor,c.Id).CustomerId);}
    [Fact]public void Restart_retains_grant_and_retention_removes_it(){var(s,c,_,code)=Issued();s.RedeemIdentity(1,visitor,c.Id,new(Guid.NewGuid(),code.Code!));Assert.Equal(42,Store().RequireIdentity(1,visitor,c.Id).CustomerId);clock.Now=clock.Now.AddDays(8);Store().Purge();Assert.Throws<AssistantException>(()=>Store().RequireIdentity(1,visitor,c.Id));}
    [Theory][InlineData("đơn hàng của tôi",true)][InlineData("tôi có bao nhiêu điểm",true)][InlineData("tra cứu đơn",true)][InlineData("chính sách tích điểm thế nào",false)][InlineData("giá sữa TH 180ml",false)]
    public void Personal_queries_use_private_panel_but_general_policy_and_catalog_remain_AI(string message,bool expected)=>Assert.Equal(expected,CustomerBusinessRead.PrivateQuery(message));
    public void Dispose(){if(Directory.Exists(directory))Directory.Delete(directory,true);}
}